function catalog(values: readonly string[]): Record<string, string> {
  const complete = values.length === KEYS.length
    ? values
    : [
        ...values,
        ...KEYS.slice(values.length).map((key) => PAGE_LOCALES_CJK["zh-CN"][key] ?? key),
      ];
  if (complete.length !== KEYS.length) throw new Error("Indic page locale catalog is incomplete");
  return Object.fromEntries(KEYS.map((key, index) => [key, complete[index]]));
}

