  "ਸਵਿੱਚਕੰਟਰੋਲ ਤੁਹਾਨੂੰ ਹਰ ਤਬਦੀਲੀ ਨੂੰ ਲਾਗੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਇਸਦਾ ਸਪਸ਼ਟ ਦ੍ਰਿਸ਼ ਦਿੰਦਾ ਹੈ। ਹਰੇਕ ਵਿਕਲਪ ਵਿੱਚ ਇੱਕ ਸਾਦੀ ਭਾਸ਼ਾ ਦੀ ਵਿਆਖਿਆ, ਇੱਕ ਜੋਖਮ ਰੇਟਿੰਗ, ਅਤੇ ਅਸਲ ਸੈਟਿੰਗ ਦਾ ਰਿਕਾਰਡ ਸ਼ਾਮਲ ਹੁੰਦਾ ਹੈ। ਤੁਸੀਂ ਆਪਣੇ ਇਤਿਹਾਸ ਦੀ ਸਮੀਖਿਆ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਲੋੜ ਪੈਣ 'ਤੇ ਤਬਦੀਲੀਆਂ ਨੂੰ ਉਲਟਾ ਸਕਦੇ ਹੋ।",
