  "AI ਸਲਾਹਕਾਰ ਕਿਹੜੀ ਜਾਣਕਾਰੀ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ?",
  "AI ਸਲਾਹਕਾਰ ਤੁਹਾਡੇ ਪ੍ਰੋਸੈਸਰ, ਗ੍ਰਾਫਿਕਸ ਕਾਰਡ, ਮੈਮੋਰੀ, ਅਤੇ ਕੋਰ ਕੌਂਫਿਗਰੇਸ਼ਨ ਸਮੇਤ, ਉਸ ਹਾਰਡਵੇਅਰ 'ਤੇ ਵਿਚਾਰ ਕਰਦਾ ਹੈ ਜਿਸ ਨੂੰ SwitchControl ਪਛਾਣ ਸਕਦਾ ਹੈ। ਇਹ ਸਪੱਸ਼ਟੀਕਰਨ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ ਅਤੇ ਅਗਲੇ ਕਦਮਾਂ ਦਾ ਸੁਝਾਅ ਦਿੰਦਾ ਹੈ, ਪਰ ਇਹ ਤੁਹਾਡੀ ਮਨਜ਼ੂਰੀ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡੇ ਕੰਪਿਊਟਰ ਨੂੰ ਨਹੀਂ ਬਦਲਦਾ ਹੈ।",
