  "EAC, Vanguard, FACEIT மற்றும் BattlEye ஆதரிக்கப்படுகின்றன. SwitchControl Windows அமைப்புகளை மட்டுமே மாற்றுகிறது. இது செயல்முறைகளில் உட்செலுத்தாது, கர்னல் ஹுக்குகளைப் பயன்படுத்தாது, கேம் கோப்புகளை மாற்றாது.",
  "முழுமையாக மீட்டமைக்கும் உத்தரவாதம்", "ஒவ்வொரு மாற்றமும் பதிவு செய்யப்படும். History பக்கத்தில் ஒரே கிளிக்கில் தனிப்பட்ட மாற்றங்களையோ முழு அமர்வையோ மீட்டமைக்கவும். நீங்கள் விரும்பினால் தவிர எதுவும் நிரந்தரமல்ல.",
  "AI ஆலோசகர், வன்பொருள் அறிந்தது", "AI ஆலோசகர் உங்கள் CPU, GPU, RAM உள்ளமைவைப் பயன்படுத்தி உங்கள் கணினிக்கான வழிகாட்டலை வழங்குகிறது. அதன் பரிந்துரைகள் பொதுவான பட்டியலை அல்ல, உங்கள் வன்பொருளை அடிப்படையாகக் கொண்டவை.",
  "பவர் திட்டத்தின் தாக்கம்", "AMD Ryzen கணினிகளில் பவர் திட்டங்கள் மிகப்பெரிய தாக்கத்தை ஏற்படுத்தலாம். உங்கள் வன்பொருள் ஆதரித்தால் சரியான சுயவிவரம் பூஸ்ட் கிளாக் நடத்தை, நினைவக தாமதம் மற்றும் திட்டமிடலைப் பாதிக்கலாம்.",
