  "இன்னும் கேள்வி இருக்கிறதா?", "Discord-இல் சேருங்கள். நாங்கள் கேள்விகளுக்கு விரைவாகப் பதிலளிக்கிறோம்; சமூகமும் பல பொதுவான அமைப்பு சூழல்களை ஏற்கனவே கையாண்டுள்ளது.", "Discord-இல் சேருங்கள்", "எங்களுக்கு மின்னஞ்சல் செய்யுங்கள்", "கிடைக்கிறது",
